+// API keys, roles and the audit log (docs/DATA.md, "Access"). Keys live in
+// `apiKeys`, audit entries in `audit`; both collections are optional.
+import { createHash, timingSafeEqual } from "node:crypto";
+
+/** Roles from least to most allowed; each may do what the ones before it may. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The API key record for the secret `key`, or null when there is none. */
+export function findKey(store, key) {
+  if (typeof key !== "string" || key === "") return null;
+  const d = digest(key);
+  let found = null;
+  // Compare against every key in constant time so timing reveals nothing.
+  for (const k of store.data.apiKeys ?? []) {
+    if (timingSafeEqual(d, digest(k.key)) && !found) found = k;
+  }
+  return found;
+}
+
+/** Whether a key with `role` may do what needs `needed`. Unknown roles may do nothing. */
+export function allows(role, needed) {
+  const have = ROLES.indexOf(role);
+  return have >= 0 && have >= ROLES.indexOf(needed);
+}
+
+/** Appends an audit entry { at, keyName, method, path, status } and returns it. */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].reverse();
+}
