@@ -0,0 +1,55 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, bearer, KEYS } from "./helpers.js";
+
+test("no key or an unknown key is 401 in the error shape", async () => {
+  const { raw, store } = app();
+  const none = await raw({ path: "/items" });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  assert.match(none.headers["www-authenticate"], /^Bearer/);
+  const wrong = await raw({ path: "/items", headers: bearer("nope") });
+  assert.equal(wrong.status, 401);
+  const writes = await raw({ method: "POST", path: "/jobs/nightly", headers: { authorization: "Basic xyz" } });
+  assert.equal(writes.status, 401);
+  assert.deepEqual(store.data.audit, []);
+});
+
+test("viewers only read", async () => {
+  const { handle, store } = app(undefined, KEYS.viewer);
+  assert.equal((await handle({ path: "/items" })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(res.status, 403);
+  assert.equal(res.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+  assert.equal((await handle({ path: "/audit" })).status, 403);
+});
+
+test("cooks cook, waste, log temperatures and count, but nothing else", async () => {
+  const { handle, store } = app(undefined, KEYS.cook);
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/6/waste", body: { qty: 0.5 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).status, 403);
+  const take = (await app(store).handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: 6, counted: 12 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/orders/3/send" })).status, 403);
+  assert.equal((await handle({ method: "PUT", path: "/items/1/allergens", body: { allergens: [] } })).status, 403);
+  assert.equal((await handle({ path: "/audit" })).status, 403);
+});
+
+test("writes are audited, newest first, and only managers read the audit", async () => {
+  const { handle, store } = app(undefined, KEYS.cook);
+  await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  await handle({ method: "POST", path: "/orders/3/send" });
+  await handle({ path: "/items" });
+  const manager = app(store);
+  const res = await manager.handle({ path: "/audit" });
+  assert.equal(res.status, 200);
+  assert.deepEqual(res.body, [
+    { at: "2026-10-28T10:00:00.000Z", keyName: "dev cook", method: "POST", path: "/orders/3/send", status: 403 },
+    { at: "2026-10-28T10:00:00.000Z", keyName: "dev cook", method: "POST", path: "/recipes/1/cook", status: 200 },
+  ]);
+});
